/*
 * prog55_connected_components.c
 *
 * Re‑implementation of the original program whose behaviour was observed
 * in the supplied binary.  The program expects a graph description on the
 * command line and prints the connected components of the (undirected)
 * graph.  The original binary was heavily obfuscated; the logic has been
 * recovered and expressed in clear C.
 *
 * Usage
 * -----
 *   prog55_connected_components N M u1 v1 u2 v2 ... uM vM
 *
 *   N – number of vertices (1 … 8)
 *   M – number of edges   (0 … N*(N‑1)/2)
 *   ui vi – endpoints of the i‑th edge (0‑based, each < N)
 *
 * Output
 * ------
 *   For each connected component the program prints a line of the form
 *
 *       C: {v0,v1,...,vk}
 *
 *   where C is the component number (starting at 0) and the vertices are
 *   listed in the order they are discovered by a breadth‑first search.
 *
 *   If any input validation fails the program prints the single line
 *
 *       INVALID_INPUT
 *
 *   and exits with status 1.
 *
 * The implementation follows the behaviour of the original binary:
 *   * maximum of 8 vertices,
 *   * adjacency matrix stored in a static 8×8 array,
 *   * visited array and a simple FIFO queue of size 8,
 *   * BFS is used to enumerate each component,
 *   * output format matches the observed `printf`/`putchar` sequence.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>

#define MAXV 8

static int adj[MAXV][MAXV];   /* adjacency matrix */
static int visited[MAXV];
static int queue_[MAXV];

static int bfs_component(int start, int *out_vertices)
{
    int head = 0, tail = 0;
    int cnt = 0;

    visited[start] = 1;
    queue_[tail++] = start;

    while (head < tail) {
        int v = queue_[head++];
        out_vertices[cnt++] = v;

        for (int w = 0; w < MAXV; ++w) {
            if (adj[v][w] && !visited[w]) {
                visited[w] = 1;
                queue_[tail++] = w;
            }
        }
    }
    return cnt;   /* number of vertices in this component */
}

int main(int argc, char **argv)
{
    /* ---------- input validation -------------------------------------- */
    if (argc < 3) {                     /* need at least N and M */
        puts("INVALID_INPUT");
        return 1;
    }

    char *endptr;
    errno = 0;
    long n = strtol(argv[1], &endptr, 10);
    if (errno || *endptr != '\0' || n < 1 || n > MAXV) {
        puts("INVALID_INPUT");
        return 1;
    }

    errno = 0;
    long m = strtol(argv[2], &endptr, 10);
    if (errno || *endptr != '\0' || m < 0 || m > n * (n - 1) / 2) {
        puts("INVALID_INPUT");
        return 1;
    }

    if (argc != 3 + 2 * m) {            /* exactly 2 arguments per edge */
        puts("INVALID_INPUT");
        return 1;
    }

    /* ---------- build adjacency matrix -------------------------------- */
    memset(adj, 0, sizeof(adj));

    for (long i = 0; i < m; ++i) {
        long u, v;

        errno = 0;
        u = strtol(argv[3 + 2 * i], &endptr, 10);
        if (errno || *endptr != '\0' || u < 0 || u >= n) {
            puts("INVALID_INPUT");
            return 1;
        }

        errno = 0;
        v = strtol(argv[4 + 2 * i], &endptr, 10);
        if (errno || *endptr != '\0' || v < 0 || v >= n) {
            puts("INVALID_INPUT");
            return 1;
        }

        adj[u][v] = adj[v][u] = 1;      /* undirected edge */
    }

    /* ---------- find connected components ----------------------------- */
    memset(visited, 0, sizeof(visited));

    int comp_id = 0;
    int component_vertices[MAXV];   /* temporary storage for one component */

    for (int v = 0; v < n; ++v) {
        if (!visited[v]) {
            int sz = bfs_component(v, component_vertices);

            /* ---------- output one component -------------------------- */
            printf("%d:", comp_id);
            printf(" {");
            for (int i = 0; i < sz; ++i) {
                printf("%d", component_vertices[i]);
                if (i + 1 < sz)
                    putchar(',');
            }
            putchar('}');
            putchar('\n');

            ++comp_id;
        }
    }

    return 0;
}
